// Dart: Variable Scope
int global = 1;
void main() {
  void inner() {
    int local = 2;
    print(global + local);
  }
  // print(local); // Error: local is undefined here
}

// Dart: Type Casting
void main() {
  double myDouble = 9.78;
  int myInt = myDouble.toInt();
  print(myInt); // Output: 9
}

// Dart: Closure
Function makeAdder(int addBy) {
  return (int i) => addBy + i;
}
void main() {
  var add2 = makeAdder(2);
  print(add2(3)); // Output: 5
}

// Dart: Callback
void processData(String data, Function(String) onComplete) {
  print('Processing $data...');
  onComplete('Done');
}
void main() {
  processData('Image', (result) => print(result));
}

